const body = $json.body || $json;

const comment = String(body.comment || body.text || body.message || '').trim();
const sourceUser = String(body.user || body.source_user || body.username || 'anonymous').trim();
const requestId = body.request_id || crypto.randomUUID();

if (!comment) {
  return [{ json: { skip: true, reason: 'empty_comment', request_id: requestId, comment: '', source_user: sourceUser } }];
}

const spamPatterns = [/https?:\/\//i, /t\.me\//i, /telegram/i, /casino/i, /bet/i, /crypto/i];
const isSpam = spamPatterns.some(r => r.test(comment));

return [{ json: { skip: isSpam, reason: isSpam ? 'spam_pattern' : '', comment, source_user: sourceUser, request_id: requestId } }];

