const normalize = $('Normalize + Basic Filter').first().json;

function fallback(reason) {
  return [{ json: { reply: 'Mình chưa hiểu rõ câu hỏi, bạn nói lại giúp mình nha!', emotion: 'neutral', action: 'fallback', source_user: normalize.source_user, comment: normalize.comment, request_id: normalize.request_id, llm_parse_ok: false, llm_parse_reason: reason } }];
}

let raw = '';
try { raw = $json.choices?.[0]?.message?.content ?? ''; } catch (e) { return fallback('missing_choices_message_content'); }
if (typeof raw !== 'string' || !raw.trim()) return fallback('empty_llm_content');
raw = raw.trim();
raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

let data;
try { data = JSON.parse(raw); }
catch (e1) {
  try { data = JSON.parse(JSON.parse(raw)); }
  catch (e2) { return fallback('json_parse_failed: ' + e2.message); }
}

const allowedEmotions = new Set(['neutral', 'happy', 'excited', 'sad', 'angry']);
const allowedActions = new Set(['answer', 'sell', 'ignore', 'fallback']);

let reply = String(data.reply || '').trim();
let emotion = String(data.emotion || 'neutral').trim().toLowerCase();
let action = String(data.action || 'fallback').trim().toLowerCase();

if (!reply && action !== 'ignore') { reply = 'Mình chưa hiểu rõ câu hỏi, bạn nói lại giúp mình nha!'; action = 'fallback'; }
if (!allowedEmotions.has(emotion)) emotion = 'neutral';
if (!allowedActions.has(action)) action = 'fallback';
if (reply.length > 500) reply = reply.slice(0, 497) + '...';

return [{ json: { reply, emotion, action, source_user: normalize.source_user, comment: normalize.comment, request_id: normalize.request_id, llm_parse_ok: true } }];
